fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo, switch to the 'Actions' application, and open the 'Explorer' nav item. Then perform these sub-actions IN ORDER, and as you complete each set \"checkpointReached\" to the exact checkpoint name shown: (1) actions-view-toggle — the toolbar has a view-mode toggle with three options (Card / List / Compact); click through them and confirm the action list re-renders in a visibly different layout for each (the selected option shows an active indicator); an empty list with a clear empty-state is acceptable; (2) actions-category-filter — the LEFT category tree panel; click a category node and confirm the main action list narrows to that category (breadcrumb/selection updates) or a clear empty-state appears, then click back to 'All' and confirm the full list returns; (3) actions-status-sort — open the Filters popover (funnel icon) with Status (Active/Pending/Disabled), Type (AI Generated/Custom), and Sort sections; toggle a Status checkbox and confirm the list narrows (or a no-results state) and the filter count badge updates, then pick a different Sort field and confirm the list re-orders; (4) actions-search-empty — type a term in the 'Search actions...' box and confirm the list narrows to matches, then type a nonsense term like 'zzzznotanaction' and confirm the narrowed empty-state renders with a 'No actions match your filters' message and a 'Reset filters' action, then clear/reset and confirm the list repopulates. Keep going until all sub-actions are done. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200/app/actions",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 65,
  "checkpoints": [
    {
      "name": "actions-view-toggle",
      "instruction": "reach the Explorer and switch view modes",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/actions"
        }
      ],
      "visualCriteria": [
        "The Explorer toolbar shows a view-mode toggle with card/list/compact options, switching between at least two modes visibly changes the action list layout (grid vs list rows) or a valid empty-state renders consistently, and the selected option shows an active/selected indicator"
      ]
    },
    {
      "name": "actions-category-filter",
      "instruction": "filter by category tree then return to All",
      "visualCriteria": [
        "A category tree/sidebar is visible on the left, selecting a category narrows the action list to that category (or shows a valid empty-state) with the breadcrumb/selection reflecting it, and returning to 'All' categories restores the broader list"
      ]
    },
    {
      "name": "actions-status-sort",
      "instruction": "filter by Status/Type and change Sort in the popover",
      "visualCriteria": [
        "The Filters popover shows Status, Type, and Sort sections; toggling a Status or Type option narrows the list (or shows a valid no-results state) and an active-filter count indicator appears; choosing a different Sort field visibly changes the ordering (or is accepted without error when empty)"
      ]
    },
    {
      "name": "actions-search-empty",
      "instruction": "search narrows list, nonsense term shows narrowed empty-state, reset restores",
      "visualCriteria": [
        "Typing in the 'Search actions...' box narrows the list to matches, a nonsense term shows a 'no actions match' empty-state with a reset/clear affordance (not a crash or blank area), and clearing the search or clicking Reset restores the list"
      ]
    }
  ]
}
